37	/**
38	 * Shared implementation of agent side-effect handling.
39	 *
40	 * Routes client-dispatched actions to the correct agent backend, handles
41	 * session create/dispose/list operations, tracks pending permission requests,
42	 * and wires up agent progress events to the state manager.
43	 *
44	 * Used by both the Electron utility-process path ({@link AgentService}) and
45	 * the standalone WebSocket server (`agentHostServerMain`).
46	 */
47	export class AgentSideEffects extends Disposable implements IProtocolSideEffectHandler {
48	
49		/** Maps pending permission request IDs to the provider that issued them. */
50		private readonly _pendingPermissions = new Map<string, string>();
51	
52		constructor(
53			private readonly _stateManager: SessionStateManager,
54			private readonly _options: IAgentSideEffectsOptions,
55			private readonly _logService: ILogService,
56			private readonly _fileService: IFileService,
57		) {
58			super();
59	
60			// Whenever the agents observable changes, publish to root state.
61			this._register(autorun(reader => {
62				const agents = this._options.agents.read(reader);
63				this._publishAgentInfos(agents);
64			}));
65		}
66	
67		/**
68		 * Fetches models from all agents and dispatches `root/agentsChanged`.
69		 */
70		private async _publishAgentInfos(agents: readonly IAgent[]): Promise<void> {
71			const infos = await Promise.all(agents.map(async a => {
72				const d = a.getDescriptor();
73				let models: ISessionModelInfo[];
74				try {
75					const rawModels = await a.listModels();
76					models = rawModels.map(m => ({
77						id: m.id, provider: m.provider, name: m.name,
78						maxContextWindow: m.maxContextWindow, supportsVision: m.supportsVision,
79						policyState: m.policyState,
80					}));
81				} catch {
82					models = [];
83				}
84				return { provider: d.provider, displayName: d.displayName, description: d.description, models };
85			}));
86			this._stateManager.dispatchServerAction({ type: ActionType.RootAgentsChanged, agents: infos });
87		}
88	
89		// ---- Agent registration -------------------------------------------------
90	
91		/**
92		 * Registers a progress-event listener on the given agent so that
93		 * `IAgentProgressEvent`s are mapped to protocol actions and dispatched
94		 * through the state manager. Returns a disposable that removes the
95		 * listener.
96		 */
97		registerProgressListener(agent: IAgent): IDisposable {
98			const disposables = new DisposableStore();
99			disposables.add(agent.onDidSessionProgress(e => {
100				// Track permission requests so handleAction can route responses
101				if (e.type === 'permission_request') {
102					this._pendingPermissions.set(e.requestId, agent.id);
103				}
104	
105				const turnId = this._stateManager.getActiveTurnId(e.session.toString());
106				if (turnId) {
107					const actions = mapProgressEventToActions(e, e.session.toString(), turnId);
108					if (actions) {
109						if (Array.isArray(actions)) {
110							for (const action of actions) {
111								this._stateManager.dispatchServerAction(action);
112							}
113						} else {
114							this._stateManager.dispatchServerAction(actions);
115						}
116					}
117				}
118			}));
119			return disposables;
120		}
121	
122		// ---- IProtocolSideEffectHandler -----------------------------------------
123	
124		handleAction(action: ISessionAction): void {
125			switch (action.type) {
126				case ActionType.SessionTurnStarted: {
127					const agent = this._options.getAgent(action.session);
128					if (!agent) {
129						this._stateManager.dispatchServerAction({
130							type: ActionType.SessionError,
131							session: action.session,
132							turnId: action.turnId,
133							error: { errorType: 'noAgent', message: 'No agent found for session' },
134						});
135						return;
136					}
137					const attachments = action.userMessage.attachments?.map((a): IAgentAttachment => ({
138						type: a.type,
139						path: a.path,
140						displayName: a.displayName,
141					}));
142					agent.sendMessage(URI.parse(action.session), action.userMessage.text, attachments).catch(err => {
143						this._logService.error('[AgentSideEffects] sendMessage failed', err);
144						this._stateManager.dispatchServerAction({
145							type: ActionType.SessionError,
146							session: action.session,
147							turnId: action.turnId,
148							error: { errorType: 'sendFailed', message: String(err) },
149						});
150					});
151					break;
152				}
153				case ActionType.SessionPermissionResolved: {
154					const providerId = this._pendingPermissions.get(action.requestId);
155					if (providerId) {
156						this._pendingPermissions.delete(action.requestId);
157						const agent = this._options.agents.get().find(a => a.id === providerId);
158						agent?.respondToPermissionRequest(action.requestId, action.approved);
159					} else {
160						this._logService.warn(`[AgentSideEffects] No pending permission request for: ${action.requestId}`);
161					}
162					break;
163				}
164				case ActionType.SessionTurnCancelled: {
165					const agent = this._options.getAgent(action.session);
166					agent?.abortSession(URI.parse(action.session)).catch(err => {
167						this._logService.error('[AgentSideEffects] abortSession failed', err);
168					});
169					break;
170				}
171				case ActionType.SessionModelChanged: {
172					const agent = this._options.getAgent(action.session);
173					agent?.changeModel?.(URI.parse(action.session), action.model).catch(err => {
174						this._logService.error('[AgentSideEffects] changeModel failed', err);
175					});
176					break;
177				}
178			}
179		}
